// api/edge-hello/route.ts

// 1. Opt-in to the Edge runtime for this specific API route
export const runtime = 'edge';

export async function GET(request: Request) {
  // 2. The Edge runtime has access to geo-location headers!
  // Vercel automatically injects the user's city based on their IP address.
  const city = request.headers.get('x-vercel-ip-city') ?? 'World';

  return new Response(`Hello from the Edge, user in ${city}!`, {
    status: 200,
  });
}
